using Sia.Reactors;

world.AcquireAddon<Hierarchy<ProcessTree>>();
world.AcquireAddon<Aggregator<UserId>>();
var processes = world.AcquireAddon<Mapper<ProcessId>>();

using var stage = SystemChain.Empty
    .Add<UserProcessCountSystem>()
    .CreateStage(world);

var init = ProcessFactory.Create(world, "init", 0, 1);
var shell = ProcessFactory.Create(world, "shell", 1000, 20, init);
var editor = ProcessFactory.Create(world, "editor", 1000, 21, shell);
stage.Tick();

Console.WriteLine("children of shell:");
foreach (var child in shell.Get<Node<ProcessTree>>().Children) {
    Console.WriteLine("  " + child.Get<ProcessName>().Value);
}
Console.WriteLine("id 21 resolves to editor: " + (processes[21] == editor));

new Node<ProcessTree>.View(shell, world) { IsSelfEnabled = false };
Console.WriteLine("editor follows disabled parent: "
    + !editor.Get<Node<ProcessTree>>().IsEnabled);

Notebook.Render(
    $"{init.Get<ProcessName>().Value}\n" +
    $"  └─ {shell.Get<ProcessName>().Value}\n" +
    $"       └─ {editor.Get<ProcessName>().Value}");

public readonly record struct ProcessName(string Value);
public readonly record struct UserId(int Value)
{
    public static implicit operator UserId(int value) => new(value);
}
public readonly record struct ProcessId(int Value)
{
    public static implicit operator ProcessId(int value) => new(value);
}
public sealed class ProcessTree;

public static class ProcessFactory
{
    public static Entity Create(
        World world, string name, UserId userId, ProcessId processId,
        Entity? parent = null)
        => world.Create(HList.From(
            new ProcessName(name),
            new Node<ProcessTree>(parent),
            Sid.From(userId),
            Sid.From(processId)));
}

public sealed class UserProcessCountSystem() : SystemBase(
    Matchers.Of<Aggregation<UserId>>(),
    EventUnion.Of<
        Aggregation<UserId>.EntityAdded,
        Aggregation<UserId>.EntityRemoved>())
{
    public override void Execute(WorldContext context, IEntityQuery query)
    {
        foreach (var entity in query) {
            ref readonly var group = ref entity.Get<Aggregation<UserId>>();
            Console.WriteLine(
                $"user {group.Id.Value}: {group.Group.Count} process(es)");
        }
    }
}

using Sia.Reactive;

var mount = world.Mount(
    CounterComponent.Definition,
    new CounterProps("downloads", 1));
world.FlushReactive();

var firstEntity = default(Entity);
foreach (var entity in world.Query(Matchers.Of<CounterValue>())) {
    firstEntity = entity;
    break;
}
Console.WriteLine(firstEntity.Get<CounterValue>());

mount.GetState<int>().Update(static value => value + 4);
world.FlushReactive();

var reconciledEntity = default(Entity);
foreach (var entity in world.Query(Matchers.Of<CounterValue>())) {
    reconciledEntity = entity;
    break;
}
Console.WriteLine(reconciledEntity.Get<CounterValue>());
Console.WriteLine("entity identity preserved: " + (firstEntity == reconciledEntity));

mount.Unmount();
var outputRemains = false;
foreach (var entity in world.Query(Matchers.Of<CounterValue>())) {
    outputRemains = true;
    break;
}
Console.WriteLine("reactive output removed: " + !outputRemains);

public readonly record struct CounterProps(string Label, int Initial);
public readonly record struct CounterValue(string Label, int Value);

[ReactiveComponent]
public static partial class CounterComponent
{
    public static ReactiveNode Render(in CounterProps props, ref Hooks hooks)
    {
        var count = hooks.UseState(props.Initial);
        return Reactive.Entity(HList.From(
            new CounterValue(props.Label, count.Value)));
    }
}

using var stage = SystemChain.Empty.Add<SignalTermSystem>().CreateStage(world);

var stubborn = world.Create(HList.From(new ProcessName("stubborn-daemon")));

world.Send(stubborn, SigTerm.Instance);
world.Send(stubborn, HOEvents.Cancel<SigTerm>.Instance);
stage.Tick();
Console.WriteLine(stubborn.IsValid
    ? "trapped SIGTERM and lives on."
    : "exited.");

if (stubborn.IsValid) {
    stubborn.Destroy();
}
Console.WriteLine(stubborn.IsValid
    ? "still alive?!"
    : "SIGKILL: gone for good -- entity.Destroy() can't be intercepted by anything.");

public readonly record struct ProcessName(string Value);
public sealed class SigTerm : SingletonEvent<SigTerm>, ICancellableEvent;

public sealed class SignalTermSystem() : SystemBase(
    Matchers.Any,
    EventUnion.Of<SigTerm>(),
    filter: EventUnion.Of<HOEvents.Cancel<SigTerm>>())
{
    public override void Execute(WorldContext context, IEntityQuery query)
    {
        Console.WriteLine("delivering SIGTERM...");
        foreach (var entity in query) {
            var name = entity.Get<ProcessName>().Value;
            entity.Destroy();
            Console.WriteLine($"[{name}] terminated gracefully.");
        }
    }
}

using var stage = SystemChain.Empty
    .Add<BootLogSystem>()
    .Add<RestartHistorySystem>()
    .CreateStage(world);

var sshd = world.Create(HList.From(new ProcessName("sshd"), new Uptime(0)));
stage.Tick();

sshd.Set(new Uptime(120));
sshd.Set(new Uptime(0));
stage.Tick();

sshd.Remove<Uptime>();
stage.Tick();

public readonly record struct ProcessName(string Value);
public partial record struct Uptime([Sia] float Seconds);

public sealed class BootLogSystem : EventSystemBase
{
    public override void Initialize(World world)
    {
        base.Initialize(world);
        RecordEvent<WorldEvents.Add<Uptime>>();
        RecordEvent<WorldEvents.Remove<Uptime>>();
    }

    protected override void HandleEvent<TEvent>(Entity entity, in TEvent @event)
    {
        var name = entity.Get<ProcessName>().Value;
        switch (@event) {
            case WorldEvents.Add<Uptime>:
                Console.WriteLine($"boot: {name} came online");
                break;
            case WorldEvents.Remove<Uptime>:
                Console.WriteLine($"boot: {name} went offline");
                break;
        }
    }
}

public sealed class RestartHistorySystem : ComponentEventSystemBase<Uptime>
{
    protected override void HandleEvent<TEvent>(Entity entity, in Uptime before, in TEvent @event)
    {
        if (@event is WorldEvents.Set<Uptime>) {
            var name = entity.Get<ProcessName>().Value;
            Console.WriteLine($"  {name} uptime was {before.Seconds:F0}s before this change");
        }
    }
}

using System.Collections.Concurrent;

for (var index = 0; index < 256; index++) {
    world.Create(HList.From(new ParallelJob(index)));
}

using var stage = SystemChain.Empty
    .Add<ParallelCullSystem>()
    .CreateStage(world);
stage.Tick();

public readonly record struct ParallelJob(int Index);

public sealed class ParallelCullSystem() : SystemBase(
    Matchers.Of<ParallelJob>())
{
    private readonly ConcurrentStack<Entity> _completed = [];

    public override void Execute(WorldContext context, IEntityQuery query)
    {
        query.ForEachOnParallel(this, static (system, entity) => {
            if (entity.Get<ParallelJob>().Index % 8 == 0) {
                system._completed.Push(entity);
            }
        });

        var count = 0;
        foreach (var entity in _completed) {
            entity.Destroy();
            count++;
        }
        _completed.Clear();
        Console.WriteLine($"destroyed {count} completed jobs after the parallel phase.");
    }
}

var monitor = world.AcquireAddon<SubWorldAddon>().SubWorld;

using var kernelStage = SystemChain.Empty.Add<LoadDriftSystem>().CreateStage(world);

var snapshotSystem = new LoadSnapshotSystem();
using var monitorStage = SystemChain.Empty
    .Add<LoadExtractSystem>()
    .Add<LoadSnapshotSystem>(() => snapshotSystem)
    .CreateStage(monitor.World);

for (var i = 0; i < 3; i++) {
    world.Create(HList.From(new ProcessName($"worker-{i}"), new Load(0.1f)));
}

for (var frame = 0; frame < 3; frame++) {
    Console.WriteLine($"kernel frame {frame}");
    kernelStage.Tick();          // mutate the real world
    snapshotSystem.RunExtract(); // pull a fresh read-only copy
    monitor.Tick(monitorStage);  // the "other thread" renders what it can see
}

public readonly record struct ProcessName(string Value);
public partial record struct Load([Sia] float Value);

public sealed class LoadDriftSystem() : SystemBase(Matchers.Of<Load>())
{
    public override void Execute(WorldContext context, IEntityQuery query)
    {
        foreach (var entity in query) {
            ref var load = ref entity.Get<Load>();
            load.Value = Math.Clamp(load.Value + (Random.Shared.NextSingle() - 0.4f), 0, 1);
        }
    }
}

public sealed class LoadExtractSystem() : ExtractSystemBase(
    matcher: Matchers.Any, extractMatcher: Matchers.Of<ProcessName, Load>())
{
    public override void Execute(WorldContext context, IEntityQuery query, IEntityQuery extract)
        => Console.WriteLine($"  [live query] sees {extract.Count} process(es) in the real world");
}

public readonly record struct LoadSample(int EntityId, float Value);

public sealed class LoadSnapshotSystem : SnapshotExtractSystem<LoadSample>
{
    protected override IEntityMatcher ExtractMatcher => Matchers.Of<Load>();

    protected override LoadSample Extract(Entity entity)
        => new(entity.Id.Value, entity.Get<Load>().Value);

    protected override void Render(ReadOnlySpan<LoadSample> data)
    {
        Console.WriteLine($"  [frozen snapshot] {data.Length} sample(s)");
        var bars = new List<string>();
        foreach (ref readonly var sample in data) {
            Console.WriteLine($"    pid {sample.EntityId,-6} load {sample.Value:P0}");
            var filled = (int)(sample.Value * 10);
            bars.Add($"pid {sample.EntityId,-6} {new string('#', filled)}{new string('.', 10 - filled)} {sample.Value:P0}");
        }
        Notebook.Render(string.Join('\n', bars));
    }
}

using var pool = new WorkerPoolRunner(4);
var barrier = RunnerBarrier.Get();

for (var i = 0; i < 8; i++) {
    var jobIndex = i;
    pool.Run(() => Console.WriteLine(
        $"job {jobIndex} ran on the worker holding connection {Context.Get<ConnectionSlot>().Id}"),
        barrier);
}
barrier.WaitAndReturn();

public sealed class ConnectionSlot(int id)
{
    public int Id { get; } = id;
}

public sealed class WorkerPoolRunner(int degreeOfParallelism) : ParallelRunner(degreeOfParallelism)
{
    protected override void RunWorkerThread(int id, BlockingQueue<IJob> jobs)
    {
        Context<ConnectionSlot>.Current = new ConnectionSlot(id);
        base.RunWorkerThread(id, jobs);
    }
}

using System.Buffers;
using System.IO.Compression;
using Sia.Serialization.Binary;

var save = new World();
save.Create(HList.From(new ServiceName("nginx"), new Replicas(3)));
save.Create(HList.From(new ServiceName("redis"), new Replicas(1)));

var buffer = new ArrayBufferWriter<byte>();
BinaryWorldSerializer.Serialize(ref buffer, save);

using var packed = new MemoryStream();
using (var gzip = new GZipStream(packed, CompressionLevel.SmallestSize, leaveOpen: true)) {
    gzip.Write(buffer.WrittenSpan);
}
Console.WriteLine($"packed {packed.Length} byte(s)");

using var unpacked = new MemoryStream();
using (var gzip = new GZipStream(new MemoryStream(packed.ToArray()), CompressionMode.Decompress)) {
    gzip.CopyTo(unpacked);
}

var seq = new ReadOnlySequence<byte>(unpacked.ToArray());
var restored = new World();
BinaryWorldSerializer.Deserialize(ref seq, restored);

var restoredLines = new List<string>();
foreach (var entity in restored) {
    Console.WriteLine(entity + ": " + entity.Boxed);
    restoredLines.Add(entity.Boxed.ToString() ?? "");
}
Notebook.Render("restored world:\n" + string.Join('\n', restoredLines));

save.Dispose();
restored.Dispose();

[MemoryPack.MemoryPackable]
public partial record struct ServiceName(string Value);

[MemoryPack.MemoryPackable]
public partial record struct Replicas(int Count);

using var actorWorld = new World();
actorWorld.Spawn(HList.From(new TickCount(0)));

var scheduler = actorWorld.AcquireAddon<Scheduler>();
scheduler.UseCorePipeline()
    .AddSchedule(new Schedule(CoreSchedules.Update)
        .Add<CountTicksSystem>());

using var actor = new WorldActor(actorWorld);
var ownerThread = System.Threading.Tasks.Task.Run(() => actor.Run());

actor.PostTickSchedule(scheduler, CoreSchedules.Update);
actor.PostTickSchedule(scheduler, CoreSchedules.Update);
actor.PostTickSchedule(scheduler, CoreSchedules.Update);

try {
    actorWorld.Create(HList.From(new TickCount(99)));
}
catch (InvalidOperationException error) {
    Console.WriteLine($"blocked from the notebook thread: {error.Message}");
}

actor.CompleteAndDispose(TimeSpan.FromSeconds(5));
ownerThread.Wait(TimeSpan.FromSeconds(5));

public partial record struct TickCount(int Value);

public sealed class CountTicksSystem() : SystemBase(Matchers.Of<TickCount>())
{
    public override void Execute(WorldContext context, IEntityQuery query)
        => query.ForSlice(static (ref TickCount c) => {
            c.Value++;
            Console.WriteLine($"tick {c.Value} ran on the actor's own thread");
        });
}
